import React from "react";
import InputField from "../components/InputField";

const PersonFilter = ({ handleChange, filter }) => { // ✅ Přidán `filter`
    return (
        <div className="mb-4">
            <div className="row">
                <div className="col-9">
                    <InputField
                        type="text"
                        name="identificationNumber"
                        handleChange={handleChange}
                        label="Identifikační číslo"
                        prompt="-"
                        value={filter.identificationNumber || ""} // ✅ Použít aktuální hodnotu
                    />
                </div>
                <div className="col-3">
                    <InputField
                        type="number"
                        min="1"
                        name="limit"
                        handleChange={handleChange}
                        label="Počet osob na stránku"
                        value={filter.limit || 10} // ✅ Výchozí hodnota
                    />
                </div>
            </div>
        </div>
    );
};

export default PersonFilter;
